import{_ as a,o as n,c as e,a2 as t}from"./chunks/framework.k9nOhppk.js";const u=JSON.parse('{"title":"The eye command","description":"","frontmatter":{"title":"The eye command"},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1791864160000}'),p={name:"reference/cli.md"};function i(l,s,r,o,c,h){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="the-eye-command" tabindex="-1">The eye command <a class="header-anchor" href="#the-eye-command" aria-label="Permalink to &quot;The eye command&quot;">​</a></h1><p><code>eye</code> is the one tool for Eyelang: it checks, formats, tests and runs programs, writes their API reference, and is the language server editors talk to. A program is a directory of <code>.eye</code> files; an <code>eye.toml</code> file marks its root.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><a href="#parse"><code>eye parse</code></a></td><td>print the syntax tree of files</td></tr><tr><td><a href="#fmt"><code>eye fmt</code></a></td><td>format source files</td></tr><tr><td><a href="#fix"><code>eye fix</code></a></td><td>rewrite code the language changed under, such as a durable step without its !</td></tr><tr><td><a href="#doc"><code>eye doc</code></a></td><td>write the API reference as Markdown</td></tr><tr><td><a href="#gen"><code>eye gen</code></a></td><td>write build output from a program&#39;s contracts: network policy, Go and TypeScript</td></tr><tr><td><a href="#check"><code>eye check</code></a></td><td>report errors in a program: syntax, names, types and effects</td></tr><tr><td><a href="#run"><code>eye run</code></a></td><td>run a program: main, then its jobs, kept in a journal across restarts</td></tr><tr><td><a href="#runs"><code>eye runs</code></a></td><td>list a program&#39;s job runs: status, what each waits for, and steps</td></tr><tr><td><a href="#approve"><code>eye approve</code></a></td><td>approve what a run of eye run waits for at approval!</td></tr><tr><td><a href="#decline"><code>eye decline</code></a></td><td>decline what a run of eye run waits for at approval!</td></tr><tr><td><a href="#test"><code>eye test</code></a></td><td>run the test blocks of a program</td></tr><tr><td><a href="#build"><code>eye build</code></a></td><td>compile a program to a native binary, through C</td></tr><tr><td><a href="#repl"><code>eye repl</code></a></td><td>start an interactive session: expressions, declarations and jobs</td></tr><tr><td><a href="#lsp"><code>eye lsp</code></a></td><td>run the language server for editors</td></tr><tr><td><a href="#version"><code>eye version</code></a></td><td>print the eye version</td></tr><tr><td><a href="#help"><code>eye help</code></a></td><td>show this message, or a command&#39;s: eye help build</td></tr></tbody></table><h2 id="parse" tabindex="-1">eye parse <a class="header-anchor" href="#parse" aria-label="Permalink to &quot;eye parse {#parse}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye parse [--sexp] file.eye...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Prints the syntax tree of each file and reports syntax errors.</span></span>
<span class="line"><span>  -sexp</span></span>
<span class="line"><span>    	print the normalised S-expression the conformance suite compares, one file per line</span></span></code></pre></div><h2 id="fmt" tabindex="-1">eye fmt <a class="header-anchor" href="#fmt" aria-label="Permalink to &quot;eye fmt {#fmt}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye fmt [--check] [--cold] [--syntax-only] [--stats] [file.eye | directory]...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Formats files in place; directories are searched for .eye files. With no</span></span>
<span class="line"><span>paths, formats standard input to standard output.</span></span>
<span class="line"><span>Recursive searches skip hidden directories and node_modules, unless named explicitly.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A directory&#39;s files are also checked as programs, and each public function&#39;s</span></span>
<span class="line"><span>uses clause is written from the effects its body has. A file named alone is</span></span>
<span class="line"><span>formatted for syntax only.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>At a terminal, it ends with a line saying how many files and lines it</span></span>
<span class="line"><span>formatted and how long that took; --stats breaks the time down.</span></span>
<span class="line"><span>  -check</span></span>
<span class="line"><span>    	list files that aren&#39;t formatted and exit 1 if there are any, without changing them</span></span>
<span class="line"><span>  -cold</span></span>
<span class="line"><span>    	run a fresh formatting check without reusing saved results (requires --check)</span></span>
<span class="line"><span>  -stats</span></span>
<span class="line"><span>    	after formatting paths, report counts, each phase&#39;s time and the slowest files on standard error</span></span>
<span class="line"><span>  -syntax-only</span></span>
<span class="line"><span>    	format a directory&#39;s files without checking its program, leaving uses clauses as written</span></span></code></pre></div><h2 id="fix" tabindex="-1">eye fix <a class="header-anchor" href="#fix" aria-label="Permalink to &quot;eye fix {#fix}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye fix [--check] [program-directory | file.eye]...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rewrites a program&#39;s code where the language changed under it, then formats</span></span>
<span class="line"><span>the files it changed. Today it adds the ! that a durable step needs in a job or</span></span>
<span class="line"><span>a waiting function, wherever eye check says &quot;durable step: write f!(…)&quot;:</span></span>
<span class="line"><span>  - calls that wait: sleep, approval, lock and the other waiting built-ins,</span></span>
<span class="line"><span>    and functions that wait</span></span>
<span class="line"><span>  - calls that reach outside the program: now, env.get, http.get, fs, process</span></span>
<span class="line"><span>    and random, and functions that use them</span></span>
<span class="line"><span>  - a contract&#39;s operation, and reconcile</span></span>
<span class="line"><span>  - an entity call, and read on an entity, a view or E.all</span></span>
<span class="line"><span>  - publish and start</span></span>
<span class="line"><span>It prints each change as file:line:column, and exits 1 if errors it can&#39;t fix</span></span>
<span class="line"><span>are left; eye check lists them. With no paths, fixes the program in the</span></span>
<span class="line"><span>current directory.</span></span>
<span class="line"><span>  -check</span></span>
<span class="line"><span>    	list what would change and exit 1 if anything would, without changing files</span></span></code></pre></div><h2 id="doc" tabindex="-1">eye doc <a class="header-anchor" href="#doc" aria-label="Permalink to &quot;eye doc {#doc}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye doc [--out dir] [program-directory]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Writes the API reference as Markdown: the standard library and, given a program,</span></span>
<span class="line"><span>its modules. Each public declaration gets its signature and its ## comment.</span></span>
<span class="line"><span>A [Name] in a ## comment links to that declaration; eye doc exits 1 if one</span></span>
<span class="line"><span>names nothing.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The pages go to ./api in the current directory, or to the directory --out names.</span></span>
<span class="line"><span>eye doc replaces that directory only if it is missing, empty, or holds nothing</span></span>
<span class="line"><span>but pages eye doc wrote. If it holds anything else, eye doc stops, changes</span></span>
<span class="line"><span>nothing and exits 1: pass --out with another directory.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -out string</span></span>
<span class="line"><span>    	the directory to write the Markdown pages to (default &quot;api&quot;)</span></span></code></pre></div><h2 id="gen" tabindex="-1">eye gen <a class="header-anchor" href="#gen" aria-label="Permalink to &quot;eye gen {#gen}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye gen &lt;target&gt; [flags] [program-directory]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Writes build output from a program&#39;s contracts to standard output. The program</span></span>
<span class="line"><span>must check; with no directory, it is the program in the current directory.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>targets:</span></span>
<span class="line"><span>  policy   Kubernetes network policy: which module may reach which service on which port</span></span>
<span class="line"><span>  go       Go types, client and server stub for each contract</span></span>
<span class="line"><span>  ts       TypeScript types, client and server stub for each contract</span></span>
<span class="line"><span></span></span>
<span class="line"><span>usage: eye gen policy [--namespace name] [program-directory]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Writes a Kubernetes NetworkPolicy (networking.k8s.io/v1) for each contract with</span></span>
<span class="line"><span>@port: the pods of the module that serves it accept TCP on that port only from</span></span>
<span class="line"><span>the pods of the modules whose code calls its operations, among those its @allow</span></span>
<span class="line"><span>lets call it. A module&#39;s pods carry the label eyelang.module: &lt;module&gt;, its</span></span>
<span class="line"><span>import path; the program&#39;s own module goes by the name of the program&#39;s</span></span>
<span class="line"><span>directory. When nothing in the program serves a contract, the policy selects</span></span>
<span class="line"><span>the pods labelled with the contract&#39;s own module, such as eyelang.module: notify</span></span>
<span class="line"><span>for a Notify written in another language. Tests, events and contracts without</span></span>
<span class="line"><span>@port, which are services outside the network, get no rule; nor does egress.</span></span>
<span class="line"><span>Each policy is named after the program and the contract, such as lab-notify,</span></span>
<span class="line"><span>so the policies of programs that call one service add up. For example:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  eye gen policy --namespace homelab testdata/lab | kubectl apply -f -</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -namespace namespace</span></span>
<span class="line"><span>    	the Kubernetes namespace the policies go in, such as homelab; without it they have none, and kubectl apply -n decides</span></span>
<span class="line"><span></span></span>
<span class="line"><span>usage: eye gen go [--module name] [--out directory] [--package name] [program-directory]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Writes a Go package for a module&#39;s contracts: their types, which marshal to</span></span>
<span class="line"><span>Eyelang&#39;s one JSON shape; for each contract a client, NotifyClient for</span></span>
<span class="line"><span>Notify, that calls its operations over @http; and a server stub, the</span></span>
<span class="line"><span>NotifyService interface to implement and NewNotifyHandler, an http.Handler</span></span>
<span class="line"><span>that routes requests to it the way eye run serves the contract. A command&#39;s</span></span>
<span class="line"><span>lost reply is an *Uncertain error, and a @fresh command&#39;s outcomes are</span></span>
<span class="line"><span>ErrStale and ErrExpired.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Operations without @http are left out of the client and the stub. The output</span></span>
<span class="line"><span>is a build artifact, never committed. Without --out, one module&#39;s file goes</span></span>
<span class="line"><span>to standard output; with it, each module with contracts gets a file, such as</span></span>
<span class="line"><span>notify/notify.go. For example:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  eye gen go --module notify testdata/lab &gt; notify.go</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -module module</span></span>
<span class="line"><span>    	the module whose contracts to write, by import path or name, such as notify; without it, the program&#39;s only module with contracts</span></span>
<span class="line"><span>  -out directory</span></span>
<span class="line"><span>    	a directory to write a file for each module with contracts into, instead of printing one</span></span>
<span class="line"><span>  -package name</span></span>
<span class="line"><span>    	the Go package&#39;s name; the module&#39;s name without it</span></span>
<span class="line"><span></span></span>
<span class="line"><span>usage: eye gen ts [--module name] [--out directory] [program-directory]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Writes a TypeScript module for a module&#39;s contracts: their types as the JSON</span></span>
<span class="line"><span>they are on the wire, a variant type as a union discriminated on &quot;kind&quot;; for</span></span>
<span class="line"><span>each contract a client class, NotifyClient for Notify, that calls its</span></span>
<span class="line"><span>operations over @http; and a server stub, the NotifyService interface to</span></span>
<span class="line"><span>implement and notifyHandler, a Fetch API handler from Request to Response</span></span>
<span class="line"><span>that routes requests to it the way eye run serves the contract. It compiles</span></span>
<span class="line"><span>with tsc --strict for ES2022 with the DOM library&#39;s fetch types.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Operations without @http are left out of the client and the stub. The output</span></span>
<span class="line"><span>is a build artifact, never committed. Without --out, one module&#39;s file goes</span></span>
<span class="line"><span>to standard output; with it, each module with contracts gets a file, such as</span></span>
<span class="line"><span>notify.ts. For example:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  eye gen ts --module notify testdata/lab &gt; notify.ts</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -module module</span></span>
<span class="line"><span>    	the module whose contracts to write, by import path or name, such as notify; without it, the program&#39;s only module with contracts</span></span>
<span class="line"><span>  -out directory</span></span>
<span class="line"><span>    	a directory to write a file for each module with contracts into, instead of printing one</span></span></code></pre></div><h2 id="check" tabindex="-1">eye check <a class="header-anchor" href="#check" aria-label="Permalink to &quot;eye check {#check}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye check [--syntax | --ir] [program-directory | file.eye]...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Checks programs: a directory and the modules it imports, or the program a file</span></span>
<span class="line"><span>belongs to: the nearest directory above it with an eye.toml, else its own.</span></span>
<span class="line"><span>Reports errors as file:line:column: message and exits 1 if there are any.</span></span>
<span class="line"><span>With no paths, checks the program in the current directory. Names, imports,</span></span>
<span class="line"><span>types, exhaustive matches, effects and where waiting calls may appear are checked.</span></span>
<span class="line"><span>  -ir</span></span>
<span class="line"><span>    	print the typed IR of a program that checks: each function, and each expression with its type</span></span>
<span class="line"><span>  -lir</span></span>
<span class="line"><span>    	print the low IR of a program that checks: each function at each set of types it is used at, in blocks</span></span>
<span class="line"><span>  -syntax</span></span>
<span class="line"><span>    	check only syntax, of files and of directories searched for .eye files</span></span></code></pre></div><h2 id="run" tabindex="-1">eye run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;eye run {#run}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye run [--store url | --journal file [--fresh] | --memory] [--crossings] [program-directory] [-- arguments…]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Runs main, then keeps the program&#39;s jobs going: sleeping runs wake on time,</span></span>
<span class="line"><span>schedules fire, and a restart carries on where the last run of eye stopped.</span></span>
<span class="line"><span>It stops when nothing is left to wait for, or on Ctrl-C or SIGTERM.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A program that serves a contract with impl answers it over HTTP on the</span></span>
<span class="line"><span>contract&#39;s @port until it is stopped. NOTIFY_PORT, named after the contract&#39;s</span></span>
<span class="line"><span>module, serves it on another port; 0 picks a free one, which eye run names.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Events of another service&#39;s contract that the program waits for come in as</span></span>
<span class="line"><span>POST /events/&lt;topic&gt;, on those ports and on EYE_EVENTS_PORT. The events of a</span></span>
<span class="line"><span>contract the program serves go to the base URLs in NOTIFY_EVENTS_URL.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>State is kept in the program&#39;s journal, or with --store in a Postgres database,</span></span>
<span class="line"><span>in the first schema of its search_path: postgres://…/db?search_path=lab gives</span></span>
<span class="line"><span>a program its own schema. One eye run at a time writes a journal or a schema.</span></span>
<span class="line"><span>  -crossings</span></span>
<span class="line"><span>    	count main&#39;s, each job run&#39;s and the runner&#39;s operations that would cross between</span></span>
<span class="line"><span>    	compiled code and the runner, and print them by kind on stderr when eye run ends</span></span>
<span class="line"><span>  -fresh</span></span>
<span class="line"><span>    	start with an empty journal; the old one is kept as JOURNAL.old</span></span>
<span class="line"><span>  -journal string</span></span>
<span class="line"><span>    	the journal that keeps entities, runs and events (default program-directory/.eye/journal)</span></span>
<span class="line"><span>  -memory</span></span>
<span class="line"><span>    	keep everything in memory, so nothing survives the process</span></span>
<span class="line"><span>  -memory-limit string</span></span>
<span class="line"><span>    	the memory runs may hold, which @memory and reserve! wait for, such as 512MiB (default the cgroup&#39;s limit, such as a container&#39;s, or the host&#39;s memory)</span></span>
<span class="line"><span>  -store string</span></span>
<span class="line"><span>    	keep entities, runs and events in this Postgres database, postgres://… (default $EYE_STORE)</span></span></code></pre></div><h2 id="runs" tabindex="-1">eye runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;eye runs {#runs}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye runs [--store url | --journal file] [--json | --show-replies] [program-directory] [run-id [step]]</span></span>
<span class="line"><span>       eye runs [--store url | --journal file] --retry ID | --retry-failed [program-directory]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Lists the job runs in a program&#39;s journal, or its Postgres store: each run&#39;s</span></span>
<span class="line"><span>status, what it waits for and until when, and with a run&#39;s id, its steps, with</span></span>
<span class="line"><span>what each model call spent. With a step&#39;s number too, it shows that step&#39;s</span></span>
<span class="line"><span>whole result, such as a model&#39;s reply. Without --retry, it reads without</span></span>
<span class="line"><span>changing anything, so it works while eye run is running.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--retry ID starts a failed run again once its cause is fixed, and --retry-failed</span></span>
<span class="line"><span>every failed run a retry can cure: those that ended as Unavailable (a service</span></span>
<span class="line"><span>out of reach) or DeadlinePassed. A retried run keeps its id and key, and replays</span></span>
<span class="line"><span>the steps it recorded, so a call that went through isn&#39;t made again. While</span></span>
<span class="line"><span>eye run holds the store, the retry goes to its inbox and the run starts within</span></span>
<span class="line"><span>a second; otherwise the next eye run carries it on.</span></span>
<span class="line"><span>  -journal string</span></span>
<span class="line"><span>    	the journal to read (default program-directory/.eye/journal)</span></span>
<span class="line"><span>  -json</span></span>
<span class="line"><span>    	print the runs as JSON, with every value whole</span></span>
<span class="line"><span>  -retry value</span></span>
<span class="line"><span>    	start the failed run with this id again, replaying the steps it recorded</span></span>
<span class="line"><span>  -retry-failed</span></span>
<span class="line"><span>    	start every failed run a retry can cure again</span></span>
<span class="line"><span>  -show-replies</span></span>
<span class="line"><span>    	with a run&#39;s id, show each model call&#39;s whole reply below its step</span></span>
<span class="line"><span>  -store string</span></span>
<span class="line"><span>    	read the store in this Postgres database, postgres://… (default $EYE_STORE)</span></span></code></pre></div><h2 id="approve" tabindex="-1">eye approve <a class="header-anchor" href="#approve" aria-label="Permalink to &quot;eye approve {#approve}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye approve [--id ID] [--by name] [--journal file] [program-directory] [text]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Answers, with approve, the one approval! a run of the program waits for whose</span></span>
<span class="line"><span>text contains text, or whose id is ID. When several contain text, it answers</span></span>
<span class="line"><span>none and lists them with their ids. The program&#39;s eye run picks the answer up</span></span>
<span class="line"><span>within a second, and publishes it as approvals.answered. eye runs shows what</span></span>
<span class="line"><span>each run waits for.</span></span>
<span class="line"><span>  -by string</span></span>
<span class="line"><span>    	who answers; only the person the approval asks may (default that person)</span></span>
<span class="line"><span>  -id string</span></span>
<span class="line"><span>    	the id of the approval to answer, as eye runs and an ambiguous eye approve show it</span></span>
<span class="line"><span>  -journal string</span></span>
<span class="line"><span>    	the journal to look for waiting approvals in (default program-directory/.eye/journal)</span></span></code></pre></div><h2 id="decline" tabindex="-1">eye decline <a class="header-anchor" href="#decline" aria-label="Permalink to &quot;eye decline {#decline}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye decline [--id ID] [--by name] [--journal file] [program-directory] [text]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Answers, with decline, the one approval! a run of the program waits for whose</span></span>
<span class="line"><span>text contains text, or whose id is ID. When several contain text, it answers</span></span>
<span class="line"><span>none and lists them with their ids. The program&#39;s eye run picks the answer up</span></span>
<span class="line"><span>within a second, and publishes it as approvals.answered. eye runs shows what</span></span>
<span class="line"><span>each run waits for.</span></span>
<span class="line"><span>  -by string</span></span>
<span class="line"><span>    	who answers; only the person the approval asks may (default that person)</span></span>
<span class="line"><span>  -id string</span></span>
<span class="line"><span>    	the id of the approval to answer, as eye runs and an ambiguous eye decline show it</span></span>
<span class="line"><span>  -journal string</span></span>
<span class="line"><span>    	the journal to look for waiting approvals in (default program-directory/.eye/journal)</span></span></code></pre></div><h2 id="test" tabindex="-1">eye test <a class="header-anchor" href="#test" aria-label="Permalink to &quot;eye test {#test}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye test [--run text] [-v] [--live modules [--record]] [--crossings] [program-directory]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Runs the test blocks of a program&#39;s module, each with a fresh in-memory store</span></span>
<span class="line"><span>and a clock that moves only when the test advances it. Calls to other services</span></span>
<span class="line"><span>are answered from recordings, except for the modules --live names, whose calls</span></span>
<span class="line"><span>go where eye run sends them, with the address and secret from the environment.</span></span>
<span class="line"><span>A test doesn&#39;t reach the network otherwise: a call that no with fakes(…)</span></span>
<span class="line"><span>answers and --live doesn&#39;t name fails the test.</span></span>
<span class="line"><span>  -crossings</span></span>
<span class="line"><span>    	count, for each test and each job run in it, the operations that would cross</span></span>
<span class="line"><span>    	between compiled code and the runner, and print them by kind at the end</span></span>
<span class="line"><span>  -live modules</span></span>
<span class="line"><span>    	call the real services of these modules, separated by commas (ai, http or contract modules),</span></span>
<span class="line"><span>    	instead of replaying their recordings; a test whose service has no address or secret set is skipped</span></span>
<span class="line"><span>  -record</span></span>
<span class="line"><span>    	with --live, write what the real services answered as the recordings</span></span>
<span class="line"><span>    	the fakes read, for the tests that passed</span></span>
<span class="line"><span>  -run string</span></span>
<span class="line"><span>    	run only the tests whose names contain this text</span></span>
<span class="line"><span>  -v	show what passing tests logged too</span></span></code></pre></div><h2 id="build" tabindex="-1">eye build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;eye build {#build}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye build [--test] [--target os/arch] [-o file] [-g] [--emit-c dir] [--runner] [program-directory]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Compiles a program to a native binary: C from the low IR, built with the zig</span></span>
<span class="line"><span>that eye pins, fetched into the user&#39;s cache the first time. Object files are</span></span>
<span class="line"><span>cached by the hash of what made them. The binary runs main, or with --test the</span></span>
<span class="line"><span>program&#39;s tests. The C back end compiles the core language; entities, jobs,</span></span>
<span class="line"><span>views and contracts still run in eye run.</span></span>
<span class="line"><span>  -emit-c string</span></span>
<span class="line"><span>    	write the C, the runtime&#39;s with it, into this directory instead of compiling it</span></span>
<span class="line"><span>  -g	compile without optimisation and with debug information (-O0 -g)</span></span>
<span class="line"><span>  -o string</span></span>
<span class="line"><span>    	the binary to write (default: the program&#39;s directory name, with .test for --test)</span></span>
<span class="line"><span>  -runner</span></span>
<span class="line"><span>    	link the program into the Go runner, built with the pinned Go: one binary, static on Linux (for linux and darwin targets)</span></span>
<span class="line"><span>  -target string</span></span>
<span class="line"><span>    	the platform to build for: darwin/amd64, darwin/arm64, linux/amd64, linux/arm64, windows/amd64 (default: this machine)</span></span>
<span class="line"><span>  -test</span></span>
<span class="line"><span>    	build a binary that runs the program&#39;s test blocks, as eye test does</span></span></code></pre></div><h2 id="repl" tabindex="-1">eye repl <a class="header-anchor" href="#repl" aria-label="Permalink to &quot;eye repl {#repl}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye repl [program-directory]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Starts an interactive session: expressions print their value and type,</span></span>
<span class="line"><span>statements run, and declarations join the session. Given a program, the</span></span>
<span class="line"><span>session can use its modules. :help lists the commands.</span></span></code></pre></div><h2 id="lsp" tabindex="-1">eye lsp <a class="header-anchor" href="#lsp" aria-label="Permalink to &quot;eye lsp {#lsp}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye lsp [--definition | --type-definition | --references | --implementation | --declaration | --hover FILE:LINE:COLUMN]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Runs the language server, speaking LSP on standard input and output.</span></span>
<span class="line"><span>Editors start it; see editors/vscode. With one of the flags it answers one</span></span>
<span class="line"><span>request as an editor would get it and prints the locations as</span></span>
<span class="line"><span>path:line:column, or a hover&#39;s Markdown, which checks the server</span></span>
<span class="line"><span>without an editor.</span></span>
<span class="line"><span>  -declaration FILE:LINE:COLUMN</span></span>
<span class="line"><span>    	print the SPECS.md section of the keyword at FILE:LINE:COLUMN, and exit</span></span>
<span class="line"><span>  -definition FILE:LINE:COLUMN</span></span>
<span class="line"><span>    	print where the name or keyword at FILE:LINE:COLUMN is defined, and exit</span></span>
<span class="line"><span>  -hover FILE:LINE:COLUMN</span></span>
<span class="line"><span>    	print the signature and doc comment of the name at FILE:LINE:COLUMN, and exit</span></span>
<span class="line"><span>  -implementation FILE:LINE:COLUMN</span></span>
<span class="line"><span>    	print every place eye implements the keyword at FILE:LINE:COLUMN, and exit</span></span>
<span class="line"><span>  -references FILE:LINE:COLUMN</span></span>
<span class="line"><span>    	print every use of the name at FILE:LINE:COLUMN, and exit</span></span>
<span class="line"><span>  -type-definition FILE:LINE:COLUMN</span></span>
<span class="line"><span>    	print where the type of what is at FILE:LINE:COLUMN is declared, and exit</span></span></code></pre></div><h2 id="version" tabindex="-1">eye version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;eye version {#version}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye version</span></span></code></pre></div><h2 id="help" tabindex="-1">eye help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;eye help {#help}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usage: eye help</span></span></code></pre></div>`,35)])])}const m=a(p,[["render",i]]);export{u as __pageData,m as default};
